import express from 'express';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { BookmarkStore, ValidationError } from './store.js';
import { fetchMetadata } from './metadata.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = join(__dirname, '..', 'public');
const DEFAULT_DATA = process.env.BOOKMARKS_DATA || join(__dirname, '..', 'data', 'bookmarks.json');

export function createApp({ dataFile = DEFAULT_DATA, metadataFetcher = fetchMetadata } = {}) {
  const store = new BookmarkStore(dataFile);
  const app = express();
  app.use(express.json({ limit: '256kb' }));

  // --- API -----------------------------------------------------------------
  app.get('/api/bookmarks', (_req, res) => {
    res.json({ items: store.list() });
  });

  // Look up a page's title/description/icon for the save form (SCN-001 / SCN-006).
  app.post('/api/metadata', async (req, res) => {
    const { url } = req.body || {};
    if (!url || typeof url !== 'string') return res.status(400).json({ ok: false });
    const meta = await metadataFetcher(url);
    res.json(meta);
  });

  app.post('/api/bookmarks', (req, res) => {
    try {
      const result = store.create(req.body || {});
      if (result.duplicate) return res.status(409).json({ duplicate: true, item: result.item });
      res.status(201).json({ item: result.item });
    } catch (err) {
      if (err instanceof ValidationError) return res.status(400).json({ error: err.message });
      throw err;
    }
  });

  app.put('/api/bookmarks/:id', (req, res) => {
    try {
      const result = store.update(Number(req.params.id), req.body || {});
      if (result === null) return res.status(404).json({ error: 'Not found' });
      if (result.conflict) return res.status(409).json({ conflict: true, item: result.item });
      res.json({ item: result.item });
    } catch (err) {
      if (err instanceof ValidationError) return res.status(400).json({ error: err.message });
      throw err;
    }
  });

  app.delete('/api/bookmarks/:id', (req, res) => {
    const ok = store.remove(Number(req.params.id));
    if (!ok) return res.status(404).json({ error: 'Not found' });
    res.json({ ok: true });
  });

  app.post('/api/bookmarks/:id/archived', (req, res) => {
    const item = store.setArchived(Number(req.params.id), !!(req.body || {}).archived);
    if (!item) return res.status(404).json({ error: 'Not found' });
    res.json({ item });
  });

  app.post('/api/bookmarks/:id/unread', (req, res) => {
    const item = store.setUnread(Number(req.params.id), !!(req.body || {}).unread);
    if (!item) return res.status(404).json({ error: 'Not found' });
    res.json({ item });
  });

  // Test-only reset, enabled solely when BOOKMARKS_TEST=1 (used by acceptance
  // tests to isolate each scenario). Never active in normal operation.
  if (process.env.BOOKMARKS_TEST === '1') {
    app.post('/api/_test/reset', (_req, res) => {
      store.clear();
      res.json({ ok: true });
    });
  }

  // --- Static client -------------------------------------------------------
  app.use(express.static(PUBLIC_DIR));

  return { app, store };
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const port = Number(process.env.PORT) || 4000;
  const { app } = createApp();
  app.listen(port, '0.0.0.0', () => {
    console.log(`My Bookmarks listening on http://0.0.0.0:${port}`);
  });
}
// File-backed store for the personal bookmark collection.
// Single-user, personal scale (SCN goal): a JSON file is a reliable, simple
// persistence choice that survives between sessions. All mutations are written
// through immediately.

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname } from 'node:path';
import { sameUrl } from '../public/shared/filters.js';
import { hostOf } from './metadata.js';

export class BookmarkStore {
  constructor(filePath) {
    this.filePath = filePath;
    this.items = [];
    this._nextId = 1;
    this._load();
  }

  _load() {
    try {
      if (existsSync(this.filePath)) {
        const raw = JSON.parse(readFileSync(this.filePath, 'utf8'));
        if (Array.isArray(raw)) this.items = raw;
      }
    } catch {
      this.items = [];
    }
    this._nextId = this.items.reduce((max, it) => Math.max(max, Number(it.id) || 0), 0) + 1;
  }

  _persist() {
    mkdirSync(dirname(this.filePath), { recursive: true });
    writeFileSync(this.filePath, JSON.stringify(this.items, null, 2));
  }

  list() {
    return this.items.slice();
  }

  clear() {
    this.items = [];
    this._nextId = 1;
    this._persist();
  }

  get(id) {
    return this.items.find((it) => it.id === id) || null;
  }

  findByUrl(url) {
    return this.items.find((it) => sameUrl(it.url, url)) || null;
  }

  /**
   * Create a bookmark. Enforces no-duplicates (SCN-009): if the address already
   * exists (collection OR archive) returns { duplicate: true, item: existing }
   * without adding a copy. New links start unread (SCN-004).
   */
  create({ url, title, description = '', note = '', topics = [], favicon = '' }) {
    const address = String(url || '').trim();
    if (!address) throw new ValidationError('An address is required.');

    const existing = this.findByUrl(address);
    if (existing) return { duplicate: true, item: existing };

    const item = {
      id: this._nextId++,
      url: address,
      title: (title && title.trim()) || hostOf(address) || address,
      description: String(description || '').trim(),
      note: String(note || '').trim(),
      topics: normalizeTopics(topics),
      host: hostOf(address),
      favicon: String(favicon || '').trim(),
      unread: true,
      archived: false,
      created: Date.now(),
    };
    this.items.push(item);
    this._persist();
    return { duplicate: false, item };
  }

  /**
   * Update an existing bookmark's editable fields (SCN-008). Preserves created,
   * unread and archived state. Rejects an address already used by another link
   * (SCN-009) via { conflict: true }.
   */
  update(id, { url, title, description, note, topics, favicon }) {
    const item = this.get(id);
    if (!item) return null;

    if (url !== undefined) {
      const address = String(url).trim();
      if (!address) throw new ValidationError('An address is required.');
      const clash = this.items.find((it) => it.id !== id && sameUrl(it.url, address));
      if (clash) return { conflict: true, item: clash };
      item.url = address;
      item.host = hostOf(address);
    }
    if (title !== undefined) item.title = (title && title.trim()) || item.host || item.url;
    if (description !== undefined) item.description = String(description || '').trim();
    if (note !== undefined) item.note = String(note || '').trim();
    if (topics !== undefined) item.topics = normalizeTopics(topics);
    if (favicon !== undefined) item.favicon = String(favicon || '').trim();

    this._persist();
    return { item };
  }

  remove(id) {
    const before = this.items.length;
    this.items = this.items.filter((it) => it.id !== id);
    const removed = this.items.length !== before;
    if (removed) this._persist();
    return removed;
  }

  setArchived(id, archived) {
    const item = this.get(id);
    if (!item) return null;
    item.archived = !!archived;
    this._persist();
    return item;
  }

  setUnread(id, unread) {
    const item = this.get(id);
    if (!item) return null;
    item.unread = !!unread;
    this._persist();
    return item;
  }
}

export class ValidationError extends Error {}

function normalizeTopics(topics) {
  if (!Array.isArray(topics)) return [];
  const seen = new Set();
  const out = [];
  for (const raw of topics) {
    const t = String(raw || '').trim();
    if (t && !seen.has(t.toLowerCase())) {
      seen.add(t.toLowerCase());
      out.push(t);
    }
  }
  return out;
}
// Reads a linked page's title, description and site icon (SCN-001).
// Fetching is done server-side because a browser cannot read arbitrary
// cross-origin pages. When a page cannot be read, callers fall back to manual
// entry (SCN-006) — this module signals that with { ok: false }.

/** Host without a leading "www." — used as a title fallback. */
export function hostOf(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
}

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .trim();
}

function metaContent(html, patterns) {
  for (const re of patterns) {
    const m = html.match(re);
    if (m && m[1]) return decodeEntities(m[1]);
  }
  return '';
}

/**
 * Extract { title, description, favicon } from raw HTML.
 * Pure and synchronous so it can be unit-tested without the network.
 */
export function parseMetadata(html, baseUrl) {
  const source = String(html || '');
  const title =
    metaContent(source, [
      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']*)["']/i,
      /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:title["']/i,
      /<title[^>]*>([\s\S]*?)<\/title>/i,
    ]) || hostOf(baseUrl);

  const description = metaContent(source, [
    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
    /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i,
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
    /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i,
  ]);

  let favicon = '';
  const iconMatch =
    source.match(/<link[^>]+rel=["'][^"']*icon[^"']*["'][^>]+href=["']([^"']+)["']/i) ||
    source.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["'][^"']*icon[^"']*["']/i);
  try {
    favicon = iconMatch ? new URL(iconMatch[1], baseUrl).href : new URL('/favicon.ico', baseUrl).href;
  } catch {
    favicon = '';
  }

  return { title: title.trim(), description: description.trim(), favicon };
}

/**
 * Fetch a URL and return { ok, title, description, favicon }.
 * Never throws: on any failure returns { ok: false } so the caller can offer
 * manual entry (SCN-006).
 */
export async function fetchMetadata(url, { timeoutMs = 6000, fetchImpl = fetch } = {}) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false };
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return { ok: false };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetchImpl(url, {
      signal: controller.signal,
      redirect: 'follow',
      headers: { 'User-Agent': 'MyBookmarks/1.0 (+link-preview)' },
    });
    if (!res.ok) return { ok: false };
    const html = await res.text();
    const meta = parseMetadata(html, res.url || url);
    return { ok: true, ...meta };
  } catch {
    return { ok: false };
  } finally {
    clearTimeout(timer);
  }
}
