button[hidden] { display: none; }

.search-wrap { position: relative; margin-bottom: 12px; }
.search-wrap .search-icon { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); font-size: 13px; opacity: .6; }
#search { padding-left: 34px; }

.seg { display: inline-flex; border: 1px solid #ccd0d5; border-radius: 8px; overflow: hidden; margin-bottom: 14px; }
.seg button { background: #fff; color: #3c4043; font-size: 12px; font-weight: 500; padding: 7px 14px; border: none; border-right: 1px solid var(--border); border-radius: 0; }
.seg button:last-child { border-right: none; }
.seg button.active { background: var(--brand); color: #fff; }
.seg[hidden] { display: none; }

.archive-note { background: #f3f0fb; color: #4c3a7a; font-size: 12px; padding: 8px 11px; border-radius: 7px; margin: 0 0 14px; }
.archive-note[hidden] { display: none; }

.topics-bar { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; }
.chip { border: 1px solid #ccd0d5; background: #fff; color: #3c4043; font-size: 12px; padding: 5px 11px; border-radius: 999px; cursor: pointer; font-weight: 500; }
.chip:hover { background: #f2f4f7; }
.chip.active { background: var(--brand); border-color: var(--brand); color: #fff; }

.count { color: var(--muted); font-size: 13px; margin: 0 0 12px; }

.list { list-style: none; margin: 0; padding: 0; }
.item { display: flex; gap: 12px; padding: 16px 0; border-top: 1px solid #eceef0; }
.item:first-child { border-top: none; }
.item.read .title-line a { color: #6b7280; }

.favicon {
  width: 32px; height: 32px; border-radius: 6px; flex: 0 0 32px;
  background: #eaf0fb; color: var(--brand);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 15px; overflow: hidden;
}
.favicon img { width: 32px; height: 32px; display: block; }

.body { flex: 1; min-width: 0; }
.title-line { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.title-line a { color: var(--brand); text-decoration: none; font-size: 15px; font-weight: 600; overflow-wrap: anywhere; }
.title-line a:hover { text-decoration: underline; }

.badge { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 999px; white-space: nowrap; }
.badge.toread { background: #fde7d2; color: #92610a; }
.badge.read { background: #e3f4e7; color: #1a7f37; }
.badge.archived { background: #ece7f8; color: #5b3fa0; }

.topic-tags { margin-top: 6px; display: flex; flex-wrap: wrap; gap: 6px; }
.topic-tag { background: #eef1f5; color: #4a5568; font-size: 11px; padding: 2px 9px; border-radius: 999px; cursor: pointer; }
.topic-tag:hover { background: #dde3ea; }

.desc { color: #3c4043; font-size: 13px; margin-top: 4px; overflow-wrap: anywhere; }
.note {
  color: #6a4b00; font-size: 13px; margin-top: 6px;
  background: #fff8e6; border-left: 3px solid #f0c040;
  padding: 6px 9px; border-radius: 4px; overflow-wrap: anywhere;
}
.note .tag { font-weight: 600; opacity: .8; }
.url { color: var(--muted); font-size: 12px; margin-top: 6px; overflow-wrap: anywhere; }
.row-foot { display: flex; align-items: center; gap: 14px; margin-top: 8px; flex-wrap: wrap; }
.meta { color: var(--faint); font-size: 12px; }
.link-btn { background: none; color: var(--brand); border: none; padding: 0; font-size: 12px; font-weight: 600; cursor: pointer; }
.link-btn:hover { background: none; text-decoration: underline; }
.link-btn.danger { color: #c0392b; }

mark { background: #fff3b0; padding: 0 1px; border-radius: 2px; }
.empty { text-align: center; color: var(--faint); padding: 30px 10px; font-size: 14px; }
